import{_ as e,o as a,c as o,a2 as n}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Tabs & multiple windows","description":"","frontmatter":{},"headers":[],"relativePath":"en/usage.md","filePath":"en/usage.md","lastUpdated":null}'),r={name:"en/usage.md"};function s(i,t,d,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="tabs-multiple-windows" tabindex="-1">Tabs &amp; multiple windows <a class="header-anchor" href="#tabs-multiple-windows" aria-label="Permalink to &quot;Tabs &amp; multiple windows&quot;">​</a></h1><p>The app is a frameless desktop shell: a custom title bar on top (which contains a browser-style tab strip) and a web content area below.</p><h2 id="title-bar-left-→-right" tabindex="-1">Title bar (left → right) <a class="header-anchor" href="#title-bar-left-→-right" aria-label="Permalink to &quot;Title bar (left → right)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Description</th></tr></thead><tbody><tr><td>App icon + title</td><td>Shows the app name</td></tr><tr><td>Fixed-site buttons</td><td>Shown only in the <strong>core window</strong>: DeepSeek UI / Web chat / Usage &amp; top-up</td></tr><tr><td>Jump to core window</td><td>Shown only in <strong>secondary windows</strong>, to get back to the window hosting DeepSeek UI</td></tr><tr><td>Tab strip</td><td>Dynamic tabs plus <strong>+</strong> to open a new one; click empty space to drag the window, scroll to pan horizontally</td></tr><tr><td>Refresh</td><td>Shown only while one of the three fixed sites is active; reloads that page</td></tr><tr><td>Settings</td><td>Opens the settings page (the <strong>Terminal</strong> now lives there too: Settings → Terminal)</td></tr><tr><td>Minimize / maximize / close</td><td>Window controls</td></tr></tbody></table><blockquote><p>Settings is an <strong>overlay</strong>: the web content underneath is not unmounted, so switching back keeps your state.</p></blockquote><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><h3 id="fixed-tabs-core-window-only" tabindex="-1">Fixed tabs (core window only) <a class="header-anchor" href="#fixed-tabs-core-window-only" aria-label="Permalink to &quot;Fixed tabs (core window only)&quot;">​</a></h3><p>The three fixed sites always exist and <strong>cannot be closed</strong>:</p><ol><li><strong>DeepSeek UI</strong> — the embedded DeepSeek Harness main interface.</li><li><strong>Web chat</strong> — embedded <a href="https://chat.deepseek.com/" target="_blank" rel="noreferrer">chat.deepseek.com</a>.</li><li><strong>Usage / top-up</strong> — embedded <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a>.</li></ol><h3 id="dynamic-tabs" tabindex="-1">Dynamic tabs <a class="header-anchor" href="#dynamic-tabs" aria-label="Permalink to &quot;Dynamic tabs&quot;">​</a></h3><ul><li>Created by <code>target=_blank</code> / <code>window.open</code> from a page, or by clicking <strong>+</strong> in the tab strip.</li><li>No limit on how many you open.</li><li><strong>Keep-alive policy</strong>: the pages kept alive are “the fixed sites + the tabs you starred + the 3 most recent unstarred dynamic tabs”. Everything beyond that <strong>stays in the tab strip</strong>, but its page is released and reloads when you switch back.</li><li>A tab only actually loads its page once it has been <strong>opened</strong>.</li></ul><h3 id="opening-a-new-tab-with" tabindex="-1">Opening a new tab with “+” <a class="header-anchor" href="#opening-a-new-tab-with" aria-label="Permalink to &quot;Opening a new tab with “+”&quot;">​</a></h3><p>What it opens depends on the <strong>New tab</strong> setting (see <a href="/en/settings">Settings</a>):</p><ul><li><strong>Built-in new tab page</strong> (default) — a search box, a search-engine picker, and your configured site shortcuts;</li><li><strong>Custom URL</strong> — opens the fixed URL you entered.</li></ul><h3 id="tab-actions" tabindex="-1">Tab actions <a class="header-anchor" href="#tab-actions" aria-label="Permalink to &quot;Tab actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td>Click</td><td>Switch to that tab</td></tr><tr><td><code>Ctrl</code> / <code>Cmd</code> + click</td><td>Open that tab&#39;s URL in the <strong>system default browser</strong></td></tr><tr><td>Middle click</td><td>Close the tab</td></tr><tr><td>Star (☆)</td><td>Pin it alive: the page stays resident and does <strong>not</strong> consume one of the 3 keep-alive slots</td></tr><tr><td>Drag a tab</td><td><strong>Reorder</strong> within the strip; drag it onto another window&#39;s light-blue overlay to <strong>move the tab into that window</strong></td></tr><tr><td>Right click</td><td>Duplicate / close / open in new window / move to another window</td></tr></tbody></table><h2 id="address-bar" tabindex="-1">Address bar <a class="header-anchor" href="#address-bar" aria-label="Permalink to &quot;Address bar&quot;">​</a></h2><p>The address bar is shown <strong>only while a dynamic tab is active</strong> (fixed sites do not show it).</p><table tabindex="0"><thead><tr><th>Input</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>http(s):</code> / <code>about:</code></td><td>Loaded inside the app</td></tr><tr><td>Other protocols (<code>mailto:</code>, <code>tel:</code>, custom schemes…)</td><td>Handed to the system default handler</td></tr><tr><td>Anything that is not a URL</td><td>Searched with the configured <strong>default search engine</strong></td></tr></tbody></table><p>The address bar also has <strong>back / forward / reload</strong> (which turns into stop while loading).</p><h2 id="multiple-windows" tabindex="-1">Multiple windows <a class="header-anchor" href="#multiple-windows" aria-label="Permalink to &quot;Multiple windows&quot;">​</a></h2><ul><li>Right-click a tab and choose <strong>Open in new window</strong> to create a full <strong>secondary window</strong> (with its own tab strip).</li><li>Secondary windows do <strong>not</strong> have the three fixed sites; that part of the title bar shows a <strong>Jump to core window</strong> button instead.</li><li>A secondary window&#39;s OS title shows “current tab title - app name”.</li><li><strong>After the core window is closed</strong>, the earliest-opened secondary window automatically <strong>takes over</strong> as the new core window and gains the three fixed sites.</li></ul><h2 id="context-menu" tabindex="-1">Context menu <a class="header-anchor" href="#context-menu" aria-label="Permalink to &quot;Context menu&quot;">​</a></h2><p>Right-click any input field, or text you dragged over to select, to get <strong>Cut / Copy / Paste / Select all</strong>:</p><ul><li>Inside an input all three are available; with a plain text selection (not editable) you get Copy / Select all;</li><li>With no selection and nothing editable, <strong>no menu appears</strong> (the tab strip has its own right-click menu — see the tab actions above);</li><li>Input fields inside the embedded pages (DeepSeek UI, web chat, dynamic tabs) support it too.</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>The defaults are below; all three can be changed in <a href="/en/settings">Settings → Shortcuts</a> (clearing one disables it):</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl</code> / <code>Cmd</code> + <code>Alt</code> + <code>H</code></td><td><strong>System-wide</strong>: from any program, return to this app’s main window (also when minimized or hidden to the tray)</td></tr><tr><td><code>Ctrl</code> / <code>Cmd</code> + <code>T</code></td><td>Toggle between DeepSeek UI and the terminal (Settings → Terminal)</td></tr><tr><td><code>F12</code></td><td>Open / close the DevTools console (<strong>only when “Developer mode” is on</strong>)</td></tr></tbody></table><h2 id="system-tray" tabindex="-1">System tray <a class="header-anchor" href="#system-tray" aria-label="Permalink to &quot;System tray&quot;">​</a></h2><p>When hidden to tray, use the tray icon:</p><ul><li>single click: show / hide the window;</li><li>right-click menu: “Show / hide window”, “Quit (also stop dsh)”.</li></ul><blockquote><p>Closing the window does not stop dsh; on real quit the app also stops the dsh process it manages. If no tray is available, closing the last window quits the app directly.</p></blockquote>',32)])])}const g=e(r,[["render",s]]);export{p as __pageData,g as default};
